import Combine
import Foundation

// MARK: - 1. 自定义 Publisher：模拟一个带延迟和可能失败的网络服务
struct NetworkServicePublisher<Output: Decodable>: Publisher {
    typealias Failure = Error
    private let endpoint: String
    private let delay: TimeInterval

    init(endpoint: String, delay: TimeInterval = 1.0) {
        self.endpoint = endpoint
        self.delay = delay
    }

    // 核心方法：当有订阅者时开始发送数据
    func receive<S: Subscriber>(subscriber: S) where S.Input == Output, S.Failure == Failure {
        // 创建一个内部的Subject来管理事件发送
        let subject = PassthroughSubject<Output, Failure>()
        subject.subscribe(subscriber) // 将订阅者连接到Subject

        // 模拟异步网络操作
        DispatchQueue.global().asyncAfter(deadline: .now() + delay) {
            // 模拟成功或失败
            if Bool.random() {
                // 模拟成功解码
                let jsonString = "{\"message\": \"Hello from \(endpoint)\"}"
                let data = jsonString.data(using: .utf8)!
                do {
                    let decoded = try JSONDecoder().decode(Output.self, from: data)
                    subject.send(decoded) // 发送解码后的值
                    subject.send(completion: .finished) // 完成
                } catch {
                    subject.send(completion: .failure(error)) // 发送解码错误
                }
            } else {
                // 模拟网络错误
                subject.send(completion: .failure(URLError(.badServerResponse)))
            }
        }
    }
}

// 辅助结构体，用于测试Publisher
struct Message: Decodable {
    let message: String
}

// MARK: - 2. 自定义 Operator：重试操作符（简化版）
struct RetryWithCount<P: Publisher>: Publisher {
    typealias Output = P.Output
    typealias Failure = P.Failure

    let upstream: P
    let maxRetries: Int

    init(upstream: P, maxRetries: Int) {
        self.upstream = upstream
        self.maxRetries = maxRetries
    }

    func receive<S: Subscriber>(subscriber: S) where S.Input == Output, S.Failure == Failure {
        // 创建一个内部状态来跟踪重试次数
        var currentRetry = 0
        // 使用一个Subject来作为桥梁
        let subject = PassthroughSubject<Output, Failure>()
        subject.subscribe(subscriber)

        func subscribeToUpstream() {
            // 订阅上游
            let subscription = upstream.sink(
                receiveCompletion: { completion in
                    switch completion {
                    case .finished:
                        subject.send(completion: .finished) // 上游正常完成
                    case .failure(let error):
                        if currentRetry < maxRetries {
                            currentRetry += 1
                            print("Retry #\(currentRetry) after error: \(error.localizedDescription)")
                            // 简单延迟后重试（实际可加入退避逻辑）
                            DispatchQueue.global().asyncAfter(deadline: .now() + 0.5) {
                                subscribeToUpstream() // 递归调用以重新订阅
                            }
                        } else {
                            subject.send(completion: .failure(error)) // 达到最大重试次数
                        }
                    }
                },
                receiveValue: { value in
                    subject.send(value) // 传递上游的值
                }
            )
            // 注意：这里需要管理subscription的生命周期，简化示例未完全处理。
            // 实际实现中，通常会在Operator内部持有subscription，并在取消时释放。
        }

        // 开始第一次订阅
        subscribeToUpstream()
    }
}

// 为Publisher添加便捷的链式调用方法
extension Publisher {
    func retryWithCount(_ retries: Int) -> RetryWithCount<Self> {
        return RetryWithCount(upstream: self, maxRetries: retries)
    }
}

// MARK: - 3. 在SwiftUI中使用（示例）
import SwiftUI

struct CombineCustomDemoView: View {
    @State private var status = "Idle"
    @State private var cancellables = Set<AnyCancellable>()

    var body: some View {
        VStack(spacing: 20) {
            Text("Status: \(status)")
                .font(.title)

            Button("Start Network Request (with retry)") {
                status = "Loading..."
                // 创建自定义Publisher，并应用自定义操作符
                NetworkServicePublisher<Message>(endpoint: "api/data", delay: 1.0)
                    .retryWithCount(2) // 最多重试2次
                    .receive(on: DispatchQueue.main) // 回到主线程
                    .sink(
                        receiveCompletion: { completion in
                            if case .failure(let error) = completion {
                                status = "Failed after retries: \(error.localizedDescription)"
                            }
                        },
                        receiveValue: { message in
                            status = "Success: \(message.message)"
                        }
                    )
                    .store(in: &cancellables) // 存储订阅
            }
            .buttonStyle(.borderedProminent)
        }
        .padding()
    }
}

